(51711, 'Psalms 118:10', 'Psalms', 118, 10, 'رانه چاپېر وو ټول قومونه خو د څښتن په زور مې دوی کړل تباه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_10.mp3', '', 1761754199, 1761754199),
(51712, 'Psalms 118:11', 'Psalms', 118, 11, 'وو راچاپېر هغوی د هرې خوا نه په ما خو د څښتن په زور مې دوی کړل تباه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_11.mp3', '', 1761754199, 1761754199),
(51713, 'Psalms 118:12', 'Psalms', 118, 12, 'رانه چاپېر وو هغوی لکه مچیو په شان خو هغوی خاموش شول لکه د اغزیو د اور په شان د څښتن په زور مې دوی کړل تباه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_12.mp3', '', 1761754199, 1761754199),
(51714, 'Psalms 118:13', 'Psalms', 118, 13, 'سخته حمله راباندې وشوه او نژدې ؤ چې زه ماتې وخورم خو څښتن وکړلو کومک راسره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_13.mp3', '', 1761754199, 1761754199),
(51715, 'Psalms 118:14', 'Psalms', 118, 14, 'څښتن زما قوت دی او دفاع یې زما وکړه او زه یې ژغورلی یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_14.mp3', '', 1761754199, 1761754199),
(51716, 'Psalms 118:15', 'Psalms', 118, 15, 'د خدای د قوم د خېمو نه واورئ د کامیابۍ په خاطر د خوشحالۍ چیغې چې د څښتن په قوي لاس دا هرڅه شوي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_15.mp3', '', 1761754199, 1761754199),
(51717, 'Psalms 118:16', 'Psalms', 118, 16, 'مونږ بریالي شو د څښتن په قوي لاس باندې په جګړه کې د هغه په زورور قوت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_16.mp3', '', 1761754199, 1761754199),
(51718, 'Psalms 118:17', 'Psalms', 118, 17, 'زه به مړ نه شم بلکې ژوندی به یمه زه به بیان کړم کوم کارونه چې څښتن کړي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_17.mp3', '', 1761754199, 1761754199),
(51719, 'Psalms 118:18', 'Psalms', 118, 18, 'هغه راکړې راته سخته سزا خو زه یې پرېنښودم چې مړ شمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_18.mp3', '', 1761754199, 1761754199),
(51720, 'Psalms 118:19', 'Psalms', 118, 19, 'ماته کړئ خلاصې دروازې د معبد چې زه ورشم د څښتن شکر ادا کړم په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_19.mp3', '', 1761754199, 1761754199),
(51721, 'Psalms 118:20', 'Psalms', 118, 20, 'دا هغه دروازه ده چې کولای شئ څښتن ته ورشئ یوازې نېک خلک کولای شي داخل شي په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_20.mp3', '', 1761754199, 1761754199),
(51722, 'Psalms 118:21', 'Psalms', 118, 21, 'شکر کومه زه د ستا څښتنه ځکه چې سوال دې قبول کړی زما ځکه چې ماته دی نجات راکړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_21.mp3', '', 1761754199, 1761754199),
(51723, 'Psalms 118:22', 'Psalms', 118, 22, 'کومه تیږه چې رد کړې ګلکارانو وه هغه اوس شوه اصلي تیږه د تهداب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_22.mp3', '', 1761754199, 1761754199),
(51724, 'Psalms 118:23', 'Psalms', 118, 23, 'دا کار وشو د څښتن له خوا نه او عجیبه ښکاري زمونږ نظر کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_23.mp3', '', 1761754199, 1761754199),
(51725, 'Psalms 118:24', 'Psalms', 118, 24, 'دا هغه ورځ ده چې څښتن په کې کړی دی عجیبه کار راځئ چې وکړو خوشحالي او په کې خوشحاله اوسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_24.mp3', '', 1761754199, 1761754199),
(51726, 'Psalms 118:25', 'Psalms', 118, 25, 'مونږه وژغوره څښتنه، مونږه وژغوره ای څښتنه بری راکړه مونږ ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_25.mp3', '', 1761754199, 1761754199),
(51727, 'Psalms 118:26', 'Psalms', 118, 26, 'مبارک دی هغه څوک چې د څښتن په نوم راځي تاسو ته غواړو برکت مونږ د څښتن له کوره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_26.mp3', '', 1761754199, 1761754199),
(51728, 'Psalms 118:27', 'Psalms', 118, 27, 'څښتن دی خدای چې یې وځلوله خپله رڼا په مونږ د قربانۍ حیوان راولئ او د قربانګاه په کنجونو باندې یې وتړئ رسیو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_27.mp3', '', 1761754199, 1761754199),
(51729, 'Psalms 118:28', 'Psalms', 118, 28, 'ته زما خدای یې او ستا شکر کوم ته مې خدای یې، زه به ستا لویي بیان کړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_28.mp3', '', 1761754199, 1761754199),
(51730, 'Psalms 118:29', 'Psalms', 118, 29, 'د څښتن شکر کوئ، ځکه چې نېک دی هغه ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms118_verse_29.mp3', '', 1761754199, 1761754199),
(51731, 'Leviticus 6:1', 'Leviticus', 6, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_1.mp3', '', 1761754199, 1761754199),
(51732, 'Leviticus 6:2', 'Leviticus', 6, 2, '«فرض کړئ د کوم کس سره د بل چا کوم شی د امانت په توګه ایښی وي او هغه ورته دروغ ووایي چې هغه شی ورک شوی دی یا غلا شوی دی او په دې باندې د څښتن په وړاندې ګناه وکړي. یا فرض کړئ کوم شی غلا کړي یا یې د چا څخه په زور واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_2.mp3', '', 1761754199, 1761754199),
(51733, 'Leviticus 6:3', 'Leviticus', 6, 3, 'یا کوم ورک شوی شی پیدا کړي او دروغ ووایي او یا قسم وخوري چې هغه یې نه دی موندلی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_3.mp3', '', 1761754199, 1761754199),
(51734, 'Leviticus 6:6', 'Leviticus', 6, 6, 'نو هغه دې یو داسې پسه چې کوم عیب په کې نه وي او د تاوان د نذرانې په توګه څښتن ته وړاندې کیږي، کاهن ته راولي. هغه دې مناسبه بیه ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_6.mp3', '', 1761754199, 1761754199),
(51735, 'Leviticus 6:7', 'Leviticus', 6, 7, 'په دې ډول به کاهن د څښتن په حضور کې د هغه دپاره کفاره ادا کړي او هغه به وبخښل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_7.mp3', '', 1761754199, 1761754199),
(51736, 'Leviticus 6:8', 'Leviticus', 6, 8, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_8.mp3', '', 1761754199, 1761754199),
(51737, 'Leviticus 6:9', 'Leviticus', 6, 9, '«هارون او د هغه زامنو ته دا حکم ورکړه چې د سوځېدونکې نذرانې دپاره دغه اصول دي: سوځېدونکې نذرانه دې د شپې څخه تر سهاره پورې د قربانۍ په ځای باندې پاتې شي او د قربانۍ په ځای باندې باید اور بل وساتل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_9.mp3', '', 1761754199, 1761754199),
(51738, 'Leviticus 6:10', 'Leviticus', 6, 10, 'بیا به کاهن خپل د کتان نېکرونه د کتان د چپنې سره واغوندي او د سوځېدونکې نذرانې ایرې به چې د قربانۍ په ځای باندې پاتې شوې دي، لېرې کړي او د قربانۍ د ځای په څنګ کې به یې واچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_10.mp3', '', 1761754199, 1761754199),
(51739, 'Leviticus 6:11', 'Leviticus', 6, 11, 'بیا دې هغه دا کالي وباسي او نور دې واغوندي او ایرې دې د کمپ څخه دباندې یو پاک ځای ته یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_11.mp3', '', 1761754199, 1761754199),
(51740, 'Leviticus 6:12', 'Leviticus', 6, 12, 'د قربانۍ په ځای باندې باید اور بل وساتل شي او باید مړ نه شي. کاهن دې هر سهار د اور لرګي ورزیاتوي او په اور باندې دې سوځېدونکې نذرانه په ترتیب سره ږدي او په هغه باندې دې د سلامتۍ د نذرانې وازګه وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_12.mp3', '', 1761754199, 1761754199),
(51741, 'Leviticus 6:13', 'Leviticus', 6, 13, 'د قربانۍ په ځای باندې باید اور په دوامداره توګه بل وساتل شي او باید مړ نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_13.mp3', '', 1761754199, 1761754199),
(51742, 'Leviticus 6:14', 'Leviticus', 6, 14, 'د غلې دانې د نذرانې دپاره دغه اصول دي: د هارون زامن چې کاهنان دي دا نذرانه دې د قربانۍ د ځای مخې ته څښتن ته وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_14.mp3', '', 1761754199, 1761754199),
(51743, 'Leviticus 6:15', 'Leviticus', 6, 15, 'کاهن دې د ښو اوړو او تېلو څخه چې قیمتي خوشبویي ورباندې شیندل شوې ده او ټوله څښتن ته وړاندې کیږي، یو موټی د نمونې په توګه واخلي او د قربانۍ په ځای باندې دې وسوځوي. د دې نذرانې بوی په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_15.mp3', '', 1761754199, 1761754199),
(51744, 'Leviticus 6:18', 'Leviticus', 6, 18, 'د هارون هره اولاده چې نارینه وي هغه خوړلی شي. دا د هغو دوامدارو نذرانو یوه برخه ده چې تل به څښتن ته په اور باندې تیاریږي. که بل څوک هغو نذرانو ته لاس وروړي، نو د هغو سپېڅلتوب به ورته زیان ورسوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_18.mp3', '', 1761754199, 1761754199),
(51745, 'Leviticus 6:19', 'Leviticus', 6, 19, 'همدارنګه څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_19.mp3', '', 1761754199, 1761754199),
(51746, 'Leviticus 6:20', 'Leviticus', 6, 20, '«دا هغه نذرانه ده چې هارون او د هغه زامن یې باید په هغه ورځ چې هغوی په کې د کاهنانو په توګه ټاکل کیږي، څښتن ته وړاندې کړي: هغوی دې یو کیلو ګرام ښه اوړه د نذرانې په توګه څښتن ته وړاندې کړي (د غلې دانې د ورځنۍ نذرانې په اندازه). د هغې څخه دې نیم په سهار کې او نیم په ماښام کې وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_20.mp3', '', 1761754199, 1761754199),
(51747, 'Leviticus 6:21', 'Leviticus', 6, 21, 'هغه دې د تېلو سره ګډ شي او په تبۍ باندې دې پاخه شي او بیا دې میده میده شي او د غلې دانې د نذرانې په توګه دې وړاندې شي. دا یو داسې بوی دی چې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_21.mp3', '', 1761754199, 1761754199),
(51748, 'Leviticus 6:22', 'Leviticus', 6, 22, 'د هارون د اولادې څخه چې هرڅوک د لوی کاهن په توګه خدمت کوي، تل به دا نذرانه وړاندې کوي. هغه دې څښتن ته د قربانۍ په توګه ټول وسوځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_22.mp3', '', 1761754199, 1761754199),
(51749, 'Leviticus 6:23', 'Leviticus', 6, 23, 'د کاهن د غلې دانې هره نذرانه باید ټوله وسوځول شي، هغه باید ونه خوړل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_23.mp3', '', 1761754199, 1761754199),
(51750, 'Leviticus 6:24', 'Leviticus', 6, 24, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_24.mp3', '', 1761754199, 1761754199),
(51751, 'Leviticus 6:25', 'Leviticus', 6, 25, '«هارون او د هغه زامنو ته ووایه چې د ګناه د نذرانې دپاره دغه اصول دي: د ګناه د نذرانې دپاره دې حیوان په هغه ځای کې چې د سوځېدونکې نذرانې دپاره حیوانات حلالیږي، حلال شي. دا ډېره سپېڅلې نذرانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_25.mp3', '', 1761754199, 1761754199),
(51752, 'Leviticus 6:26', 'Leviticus', 6, 26, 'کاهن چې دا حیوان قرباني کوي، هغه دې په یو سپېڅلي ځای یعنې د سپېڅلې خېمې په حوېلۍ کې وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_26.mp3', '', 1761754199, 1761754199),
(51753, 'Leviticus 6:27', 'Leviticus', 6, 27, 'که یو څوک یا یو شی د دې حیوان د غوښې سره ولګیږي، د هغې سپېڅلتوب به ورته زیان ورسوي. که چېرې د کالیو کوم ځای د دې حیوان په وینه ککړ شي، هغه باید په یو سپېڅلي ځای کې ووینځل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_27.mp3', '', 1761754199, 1761754199),
(51754, 'Leviticus 6:28', 'Leviticus', 6, 28, 'د خاورو یو لوښی چې هغه غوښه په کې خوټول کیږي، باید مات شي او که چېرې د برنجو د لوښي څخه کار اخیستل کیږي، باید وموښل شي او په اوبو ووینځل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_28.mp3', '', 1761754199, 1761754199),
(51755, 'Leviticus 6:29', 'Leviticus', 6, 29, 'د کاهنانو د کورنیو هر نارینه کولای شي چې دا نذرانه وخوري، هغه ډېره سپېڅلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_29.mp3', '', 1761754199, 1761754199),
(51756, 'Leviticus 6:30', 'Leviticus', 6, 30, 'خو د ګناه کومه نذرانه چې وینه یې سپېڅلې خېمې ته راوړل کیږي چې په سپېڅلي ځای کې یې کفاره ادا شي، هغه نذرانه باید ونه خوړل شي، بلکې وسوځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus6_verse_30.mp3', '', 1761754199, 1761754199),
(51757, 'Deuteronomy 27:1', 'Deuteronomy', 27, 1, 'بیا موسی د اسراییلو د مشرانو سره ولاړ ؤ او خلکو ته یې وویل: «هغو ټولو حکمونو ته غاړه کېږدئ چې زه یې نن تاسو ته درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy27_verse_1.mp3', '', 1761754199, 1761754199),
(51758, 'Deuteronomy 27:5', 'Deuteronomy', 27, 5, 'په هغه ځای کې د قربانۍ ځای جوړ کړئ، خو د داسې تیږو څخه په کې کار مه اخلئ چې د اوسپنیز سامان په وسیله پرې کړل شوې وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy27_verse_5.mp3', '', 1761754199, 1761754199),
(51759, 'Deuteronomy 27:6', 'Deuteronomy', 27, 6, 'ځکه تاسو چې خپل څښتن خدای ته د قربانۍ ځای جوړوئ، باید د داسې تیږو څخه جوړ شي چې پرې کړل شوې نه وي. هلته باید تاسو سوځېدونکې نذرانې وړاندې کړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy27_verse_6.mp3', '', 1761754199, 1761754199),
(51760, 'Deuteronomy 27:7', 'Deuteronomy', 27, 7, 'او هلته باید خپلې د سلامتۍ نذرانې قرباني کړئ او هغه وخورئ او د خپل څښتن خدای په حضور کې خوشحالي وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy27_verse_7.mp3', '', 1761754199, 1761754199),
