(51780, 'Deuteronomy 10:1', 'Deuteronomy', 10, 1, 'بیا څښتن ماته وویل: ‹د لومړنیو لوحو په شان د تیږو دوه لوحې تیارې کړه او د لرګیو یو صندوق جوړ کړه چې هغه په کې کېږدې. بیا ماته غره ته راوخېژه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_1.mp3', '', 1761754199, 1761754199),
(51781, 'Deuteronomy 10:2', 'Deuteronomy', 10, 2, 'زه به په دې لوحو باندې هغه خبرې ولیکم چې په هغو لوحو باندې لیکلې شوې وې چې تا ماتې کړې او بیا هغه په صندوق کې کېږده.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_2.mp3', '', 1761754199, 1761754199),
(51782, 'Deuteronomy 10:3', 'Deuteronomy', 10, 3, 'نو ما د اکاسۍ د لرګیو څخه یو صندوق جوړ کړ او د لومړنیو لوحو په شان مې د تیږو دوه لوحې تیارې کړې او غره ته مې وخېژولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_3.mp3', '', 1761754199, 1761754199),
(51783, 'Deuteronomy 10:4', 'Deuteronomy', 10, 4, 'بیا څښتن په دې لوحو باندې هماغه خبرې ولیکلې چې هغه په لومړي ځل لیکلې وې، یعنې هغه لس حکمونه چې په هغه وخت کې هغه درکړل کله چې ستاسو سره یې د اور د منځ څخه خبرې وکړې. دا کار په هغه ورځ وشو چې تاسو د غره تر څنګ راټول شوي وئ. څښتن هغه لوحې ماته راکړې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_4.mp3', '', 1761754199, 1761754199),
(51784, 'Deuteronomy 10:5', 'Deuteronomy', 10, 5, 'بیا زه بېرته د غره څخه راښکته شوم. د څښتن د امر سره سم مې هغه لوحې په هماغه صندوق کې کېښودلې چې ما جوړ کړی ؤ او د هماغه وخت راهیسې په کې پرتې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_5.mp3', '', 1761754199, 1761754199),
(51785, 'Deuteronomy 10:6', 'Deuteronomy', 10, 6, 'اسراییلیان د یعقان د خلکو د څاه ګانو څخه روان شول او موسیره ته لاړل. هلته هارون مړ شو او ښخ کړای شو او د هغه زوی العازار د هغه په ځای کاهن شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_6.mp3', '', 1761754199, 1761754199),
(51786, 'Deuteronomy 10:7', 'Deuteronomy', 10, 7, 'هغوی د هغه ځای څخه جدجوده ته او بیا یطبات ته سفر وکړ، یعنې هغې خاورې ته چې د اوبو ویالې په کې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_7.mp3', '', 1761754199, 1761754199),
(51787, 'Deuteronomy 10:8', 'Deuteronomy', 10, 8, 'په هغه وخت کې څښتن د لاوي قبیله غوره کړله چې د لوظ صندوق یوسي، د کاهنانو په توګه د څښتن خدمت وکړي او د هغه په نوم برکت ورکړي. تر اوسه پورې دا د هغوی دندې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_8.mp3', '', 1761754199, 1761754199),
(51788, 'Deuteronomy 10:9', 'Deuteronomy', 10, 9, 'نو ځکه د لاوي قبیلې د نورو قبیلو په شان ځمکه تر لاسه نه کړه. ستاسو د څښتن خدای د وعدې سره سم څه چې هغوی تر لاسه کړل هغه د څښتن د کاهنتوب امتیاز ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_9.mp3', '', 1761754199, 1761754199),
(51789, 'Deuteronomy 10:10', 'Deuteronomy', 10, 10, 'زه د لومړي ځل په شان څلوېښت شپې او ورځې په غره کې پاتې شوم. څښتن یوځل بیا زما دعا قبوله کړه او په دې راضي شو چې تاسو تباه نه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_10.mp3', '', 1761754199, 1761754199),
(51790, 'Deuteronomy 10:11', 'Deuteronomy', 10, 11, 'بیا هغه ماته وویل چې لاړ شم او ستاسو مشري وکړم، ترڅو تاسو وکولای شئ هغه ځمکه تر لاسه کړئ چې هغه وعده کړې وه چې ستاسو نیکونو ته به یې ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_11.mp3', '', 1761754199, 1761754199),
(51791, 'Deuteronomy 10:12', 'Deuteronomy', 10, 12, 'د اسراییلو خلکو، ستاسو څخه خپل څښتن خدای څه غواړي؟ د هغه څخه ووېرېږئ او ټول امرونه یې په ځای کوئ. د هغه سره مینه کوئ او د زړه له کومي یې خدمت کوئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_12.mp3', '', 1761754199, 1761754199),
(51792, 'Deuteronomy 10:13', 'Deuteronomy', 10, 13, 'او د هغه د ټولو قوانینو اطاعت کوئ. زه نن دا قوانین تاسو ته ستاسو د ګټې په خاطر درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_13.mp3', '', 1761754199, 1761754199),
