(51798, 'Deuteronomy 10:19', 'Deuteronomy', 10, 19, 'نو بیا د هغو پردیو خلکو سره مینه کوئ، ځکه چې تاسو خپله یو وخت په مصر کې پردي وئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_19.mp3', '', 1761754199, 1761754199),
(51799, 'Deuteronomy 10:20', 'Deuteronomy', 10, 20, 'د خپل څښتن خدای څخه وېره کوئ او یوازې د هغه عبادت کوئ. هغه ته وفادار اوسئ او یوازې د هغه په نوم قسم خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_20.mp3', '', 1761754199, 1761754199),
(51800, 'Deuteronomy 10:21', 'Deuteronomy', 10, 21, 'د هغه ستاینه کوئ. هغه ستاسو خدای دی او تاسو هغه لوی لوی او عجیبه کارونه په خپلو سترګو ولیدل چې ستاسو دپاره یې کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_21.mp3', '', 1761754199, 1761754199),
(51801, 'Deuteronomy 10:22', 'Deuteronomy', 10, 22, 'کله چې ستاسو نیکونه مصر ته لاړل چې هلته واوسیږي، هغوی یوازې اویا تنه وو. خو اوس ستاسو څښتن خدای ستاسو شمېر د اسمان د ستورو په شان زیات کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy10_verse_22.mp3', '', 1761754199, 1761754199),
(51802, 'Daniel 6:1', 'Daniel', 6, 1, 'داريوس دا فېصله وکړه چې ټوله بادشاهى په يو سل او شل صوبو باندې تقسيم کړى، او هغۀ لوئ آفسران مقرر کړل چې په هره صوبه حکمرانى وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_1.mp3', '', 1761754199, 1761754199),
(51803, 'Daniel 6:2', 'Daniel', 6, 2, 'بادشاه دانيال او دوه نور کسان په دې آفسرانو سر پرست مقرر کړل چې په آفسرانو او د بادشاه په ګټو باندې نظر وساتى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_2.mp3', '', 1761754199, 1761754199),
(51804, 'Daniel 6:3', 'Daniel', 6, 3, 'دانيال زر دا ثابته کړه چې هغه د نورو وزيرانو او لوئ آفسرانو نه ډېر قابل دے. نو بيا ځکه بادشاه دا فېصله وکړه چې هغه په ټوله بادشاهۍ باندې حاکِم مقرر کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_3.mp3', '', 1761754199, 1761754199),
(51805, 'Daniel 6:4', 'Daniel', 6, 4, 'نو په دې وجه نور وزيران او لوئ آفسران په دې لټون کښې شُو چې د هغۀ په حکومتى انتظام کښې څۀ داسې غلطى پېدا کړى. خو هغوئ څۀ داسې هيڅ څيز د هغۀ خلاف پېدا نۀ کړلو چې هغه پرې ملامته کړى، ځکه چې هغه ډېر ايماندار وو او هيڅ قسم غلطى او بې‌ايمانى يې نۀ کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_4.mp3', '', 1761754199, 1761754199),
(51806, 'Daniel 6:5', 'Daniel', 6, 5, 'آخر هغه کسانو دا ووئيل چې، ”دې طريقې سره به مونږ په دانيال هيڅ قِسمه اِلزام ونۀ لګولے شُو. خو يوه خبر ده چې د اِلزام باعث جوړېدے شى يعنې د هغۀ د خُدائ پاک د شريعت په حقله.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_5.mp3', '', 1761754199, 1761754199),
(51807, 'Daniel 6:6', 'Daniel', 6, 6, 'نو بيا وزيران او لوئ آفسران په يو ځائ بادشاه له ورغلل او ورته يې ووئيل چې، ”داريوس بادشاه دې د تل دپاره ژوندے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_6.mp3', '', 1761754199, 1761754199),
(51808, 'Daniel 6:7', 'Daniel', 6, 7, 'مونږ د ټول مُلک شاهى وزيران، آفسران، مشيران، مشران او حاکمان په دې راضى شوى يُو چې بادشاه دې يو فرمان جارى کړى او په سختۍ سره دې په هغې عمل وکړے شى چې په راتلونکو دېرشو ورځو کښې هر څوک چې هم ستا نه بغېر د بل معبود يا انسان عبادت وکړى، نو هغه دې د زمرو په غار کښې واچولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_7.mp3', '', 1761754199, 1761754199),
(51809, 'Daniel 6:8', 'Daniel', 6, 8, 'نو اوس، اے بادشاه سلامت، دا حکم جارى کړه او مهر پرې ولګوه چې څوک هم دا بدل نۀ کړے شى، لکه د ميديانو او فارسيانو د قانون په مطابق چې نۀ منسوخ کېدونکے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_8.mp3', '', 1761754199, 1761754199),
(51810, 'Daniel 6:9', 'Daniel', 6, 9, 'نو بيا داريوس بادشاه په ليکل شوے فرمان دستخط وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel6_verse_9.mp3', '', 1761754199, 1761754199);